use std::sync::{Arc, Mutex};

/// Where notes rows are kept. Services depend only on this trait.
#[async_trait]
pub trait NoteRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: i32) -> Result<Option<Note>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Note>, DomainError>;

    /// Rows with this authorId, by primary key.
    async fn list_by_author_id(&self, author_id: i32) -> Result<Vec<Note>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Note) -> Result<Note, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Note) -> Result<Note, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Note) -> Result<(), DomainError>;
}

/// Keeps notes rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoNoteRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoNoteRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl NoteRepository for MongoNoteRepository<'_> {
    async fn find_by_id(&self, id: i32) -> Result<Option<Note>, DomainError> {
        let found = self.db.find_one("notes", doc! { "_id": bson_values::of_i32(&id)? }).await?;
        Ok(found.as_ref().map(Note::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Note>, DomainError> {
        let total = self.db.count("notes", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("notes", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Note::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn list_by_author_id(&self, author_id: i32) -> Result<Vec<Note>, DomainError> {
        let found = self.db.find("notes", doc! { "authorId": bson_values::of_i32(&author_id)? }, doc! { "_id": 1 }, 0, 0).await?;
        Ok(found.iter().map(Note::from_document).collect::<Result<_, _>>()?)
    }

    async fn insert(&self, entity: Note) -> Result<Note, DomainError> {
        let mut entity = entity;
        let document = entity.to_document()?;
        self.db.insert("Note", "notes", &document).await?;
        entity.loaded = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Note) -> Result<Note, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded.0.as_ref(), &now, &["text", "authorId"]);
        if !changes.is_empty() {
            self.db.update("Note", "notes", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Note) -> Result<(), DomainError> {
        let id = entity.id.expect("id is set");
        self.db.delete("Note", "notes", doc! { "_id": bson_values::of_i32(&id)? }).await
    }
}

/// Keeps notes rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryNoteRepository {
    rows: Arc<Mutex<Vec<Note>>>,
}

impl MemoryNoteRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Note> {
        let mut rows: Vec<Note> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Note) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Note) -> (Option<i32>,) {
    (row.id,)
}

#[async_trait]
impl NoteRepository for MemoryNoteRepository {
    async fn find_by_id(&self, id: i32) -> Result<Option<Note>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Note>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn list_by_author_id(&self, author_id: i32) -> Result<Vec<Note>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.author_id.as_ref() == Some(&author_id)).collect())
    }

    async fn insert(&self, entity: Note) -> Result<Note, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Note) -> Result<Note, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Note) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

