//! The service of the "notes" table.

use crate::common::Page;
use crate::dtos::note::{NoteCreate, NoteRead, NoteUpdate};
use crate::entities::note::Note;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on notes. Repositories commit every write.
pub struct NoteService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl NoteService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Note after checking it.
    pub async fn create_note(&self, data: NoteCreate) -> Result<NoteRead, DomainError> {
        let values = Values { id: data.id.map(Some), text: data.text.map(Some), author_id: data.author_id.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Note::default();
        apply_values(&mut entity, &values);
        let created = uow.notes().insert(entity).await?;
        Ok(read(created))
    }

    /// The Note with this key; NotFound when there is none.
    pub async fn get_note(&self, id: i32) -> Result<NoteRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of notes, by primary key.
    pub async fn list_notes(&self, offset: u64, limit: u64) -> Result<Page<NoteRead>, DomainError> {
        self.unit_of_work.notes().list(offset, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Note.
    pub async fn update_note(&self, id: i32, changes: NoteUpdate) -> Result<NoteRead, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.notes().update(current).await?;
        Ok(read(updated))
    }

    /// Deletes a Note.
    pub async fn delete_note(&self, id: i32) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.notes().delete(&current).await?;
        Ok(())
    }

    /// The notes with this authorId.
    pub async fn list_notes_by_author_id(&self, author_id: i32) -> Result<Vec<NoteRead>, DomainError> {
        self.unit_of_work.notes().list_by_author_id(author_id).await.map(|rows| rows.into_iter().map(read).collect())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    id: Option<Option<i32>>,
    text: Option<Option<String>>,
    author_id: Option<Option<i32>>,
}

/// Checks the values against the rules of the "notes" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Note>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.text.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.text.is_some() {
                errors.push(FieldError::new("text", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.author_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.author_id.is_some() {
                errors.push(FieldError::new("authorId", "is required"));
            }
        }
        Some(_) => {}
    }
    {
        let author_id = values.author_id.clone().unwrap_or_else(|| current.and_then(|current| current.author_id));
        if let Some(author_id) = author_id {
            if uow.users().find_by_id(author_id).await?.is_none() {
                errors.push(FieldError::new("authorId", "no User has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Note".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Note>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Note, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = *value;
    }
    if let Some(value) = &values.text {
        entity.text = value.clone();
    }
    if let Some(value) = &values.author_id {
        entity.author_id = *value;
    }
}

/// The values an update gives, by field.
fn given(changes: NoteUpdate) -> Values {
    Values { text: changes.text.given(), author_id: changes.author_id.given(), ..Default::default() }
}

/// The Note with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i32) -> Result<Note, DomainError> {
    uow.notes().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Note", id))
}

/// The Note as services return it.
fn read(entity: Note) -> NoteRead {
    NoteRead {
        id: entity.id.expect("id is set"),
        text: entity.text.expect("text is set"),
        author_id: entity.author_id.expect("author_id is set"),
    }
}

