    }

    /// Deletes a User.
    pub async fn delete_user(&self, id: i32) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        if !uow.notes().list_by_author_id(current.id.expect("id is set")).await?.is_empty() {
            return Err(DomainError::conflict("User", "rows of notes still point to it", &["notes"]));
        }
        uow.users().delete(&current).await?;
        Ok(())
    }

    /// The User with this email, or None.
    pub async fn find_user_by_email(&self, email: String) -> Result<Option<UserRead>, DomainError> {
        self.unit_of_work.users().find_by_email(email).await.map(|row| row.map(read))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    id: Option<Option<i32>>,
    email: Option<Option<String>>,
}

/// Checks the values against the rules of the "users" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&User>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "User".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&User>) -> Result<(), DomainError> {
    {
        let email = values.email.clone().unwrap_or_else(|| current.and_then(|current| current.email.clone()));
        if let Some(email) = email {
            if let Some(other) = uow.users().find_by_email(email).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("User", "email is already taken", &["email"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&User>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut User, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = *value;
    }
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: UserUpdate) -> Values {
    Values { email: changes.email.given(), ..Default::default() }
}

/// The User with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i32) -> Result<User, DomainError> {
    uow.users().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("User", id))
}

/// The User as services return it.
fn read(entity: User) -> UserRead {
    UserRead {
        id: entity.id.expect("id is set"),
        email: entity.email.expect("email is set"),
    }
}

