//! The unit of work: the repositories of every table, and the transactions that group their writes.

use async_trait::async_trait;
use crate::database::Db;
use crate::errors::DomainError;
use crate::repositories::note::{MemoryNoteRepository, NoteRepository, MongoNoteRepository};
use crate::repositories::user::{MemoryUserRepository, MongoUserRepository, UserRepository};
use mongodb::{ClientSession, Database};
use std::sync::Arc;
use tokio::sync::Mutex;

/// What services depend on: a repository per table and transactions. Every repository write is committed at once; services open no transaction.
#[async_trait]
pub trait UnitOfWork: Send + Sync {
    fn users(&self) -> Box<dyn UserRepository + '_>;
    fn notes(&self) -> Box<dyn NoteRepository + '_>;

    /// A unit of work in a new transaction: its changes are kept when it is committed, and dropped otherwise.
    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError>;

    /// Keeps the changes of the transaction this unit of work is in.
    async fn commit(self: Box<Self>) -> Result<(), DomainError>;
}

/// The repositories over one database, and its transactions.
pub struct MongoUnitOfWork {
    db: Db,
    /// Whether someone else opened the transaction, and commits it
    joined: bool,
}

impl MongoUnitOfWork {
    /// The repositories over a database: every write outside a transaction is stored at once.
    pub fn new(database: Database) -> Self {
        Self { db: Db { database, session: None }, joined: false }
    }

    /// The repositories inside the transaction of a session someone else opened; commit() commits it.
    pub fn in_transaction(database: Database, session: ClientSession) -> Self {
        Self { db: Db { database, session: Some(Arc::new(Mutex::new(session))) }, joined: false }
    }
}

#[async_trait]
impl UnitOfWork for MongoUnitOfWork {
    fn users(&self) -> Box<dyn UserRepository + '_> {
        Box::new(MongoUserRepository::new(&self.db))
    }

    fn notes(&self) -> Box<dyn NoteRepository + '_> {
        Box::new(MongoNoteRepository::new(&self.db))
    }

    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError> {
        // Joins the transaction already open: whoever opened it commits it
        if self.db.session.is_some() {
            return Ok(Box::new(MongoUnitOfWork { db: self.db.clone(), joined: true }));
        }
        let mut session = self.db.database.client().start_session().await?;
        session.start_transaction().await?;
        Ok(Box::new(MongoUnitOfWork::in_transaction(self.db.database.clone(), session)))
    }

    async fn commit(self: Box<Self>) -> Result<(), DomainError> {
        if let (Some(session), false) = (&self.db.session, self.joined) {
            session.lock().await.commit_transaction().await?;
        }
        Ok(())
    }
}

/// The in-memory repositories, for tests and for trying the services without a database. Memory has no
/// transactions: changes are kept as they are made, and every copy of it shares the same rows.
#[derive(Clone, Default)]
pub struct MemoryUnitOfWork {
    users: MemoryUserRepository,
    notes: MemoryNoteRepository,
}

#[async_trait]
impl UnitOfWork for MemoryUnitOfWork {
    fn users(&self) -> Box<dyn UserRepository + '_> {
        Box::new(self.users.clone())
    }

    fn notes(&self) -> Box<dyn NoteRepository + '_> {
        Box::new(self.notes.clone())
    }

    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError> {
        Ok(Box::new(self.clone()))
    }

    async fn commit(self: Box<Self>) -> Result<(), DomainError> {
        Ok(())
    }
}

