//! Rows for the tests: valid values for every column, and the rows they point to.

// Not every test uses every factory
#![allow(dead_code)]

use mongorust_mongodb_from_model2db_validators::entities::note::Note;
use mongorust_mongodb_from_model2db_validators::entities::user::User;
use mongorust_mongodb_from_model2db_validators::unit_of_work::UnitOfWork;

/// A valid User that is not stored yet; n makes its unique values differ.
pub fn new_user(n: i32) -> User {
    User {
        id: Some(n),
        email: Some(format!("email-{n}")),
        ..Default::default()
    }
}

/// A stored User.
pub async fn add_user(uow: &dyn UnitOfWork, n: i32) -> User {
    let entity = new_user(n);
    uow.users().insert(entity).await.expect("a stored User")
}

/// A valid Note that is not stored yet; n makes its unique values differ.
pub fn new_note(n: i32) -> Note {
    Note {
        id: Some(n),
        text: Some(format!("text-{n}")),
        ..Default::default()
    }
}

/// A stored Note, with the rows it points to.
pub async fn add_note(uow: &dyn UnitOfWork, n: i32) -> Note {
    let parent0 = add_user(uow, n).await;
    let mut entity = new_note(n);
    entity.author_id = parent0.id;
    uow.notes().insert(entity).await.expect("a stored Note")
}

