#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_note(&uow, 1).await;
    let found = uow.notes().find_by_id(stored.id.expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
