async fn changes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = NoteService::new(uow.clone());
    let parent0 = factories::add_user(uow.as_ref(), 100).await;
    let mut row = factories::new_note(1);
    row.author_id = parent0.id;
    let created = service.create_note(create_of(row.clone())).await.expect("a create");
    let updated = service.update_note(created.id, NoteUpdate { text: Patch::Set(Some("changed".to_string())), ..Default::default() }).await.expect("an update");
